export function usMortgageRiskSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !US_MORTGAGE_RISK_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid US mortgage risk figure variant');
  return snippets[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
